// Listing reads the authenticated socket and runs outside the per-session turn lock.
async function answerSessionList(
  ws: WebSocket,
  store: SessionStore | undefined,
  options: import('../../types/messages.js').ListSessionsMessage
): Promise<void> {
  const userId = (ws as ExtWebSocket).userId;
  try {
    const summaries = await store?.listFor?.(userId, {limit: options.limit, before: options.before});
    sendJson(ws, {
      type: 'session_list',
      sessions: (summaries ?? []).map(summary => ({
        sessionId: summary.sessionId,
        createdAt: summary.createdAt.toISOString(),
        updatedAt: summary.updatedAt.toISOString(),
        entryCount: summary.entryCount,
      })),
    });
  } catch (error) {
    log.error('ws', 'session list failed', {userId, error: error instanceof Error ? error.message : String(error)});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

